import{_ as a}from"./chunks/console-applications.BAb8jNxE.js";import{_ as t,o,c as s,a3 as r}from"./chunks/framework.DhF4LrUq.js";const n="/shipperdog/snapshot/screenshots/roles/console-owner-dashboard.png",m=JSON.parse('{"title":"App Owner quickstart","description":"Quickstart for App Owners — the application registry, versions and tags, the Product approval step, release manifests, and dashboards.","frontmatter":{"description":"Quickstart for App Owners — the application registry, versions and tags, the Product approval step, release manifests, and dashboards."},"headers":[],"relativePath":"roles/app-owner.md","filePath":"roles/app-owner.md"}'),i={name:"roles/app-owner.md"};function l(p,e,h,d,c,g){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="app-owner-quickstart" tabindex="-1">App Owner quickstart <a class="header-anchor" href="#app-owner-quickstart" aria-label="Permalink to &quot;App Owner quickstart&quot;">​</a></h1><h2 id="who-you-are" tabindex="-1">Who you are <a class="header-anchor" href="#who-you-are" aria-label="Permalink to &quot;Who you are&quot;">​</a></h2><p>You own one or more applications on ShipperDog — the product side of the house. Your system role is <strong><code>APP_OWNER</code></strong>, held on your organization membership, and your surface is the Console. You register the application, own its version history, sign the Product step of each release&#39;s approval chain, watch its dashboards, and decide (with tenant administrators) who can see shared applications. You are not the one uploading builds — that is the <a href="/shipperdog/snapshot/roles/developer">Developer</a> track — but everything around the build is yours.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><ul><li><strong>Own the registry entry</strong> — register applications, pin their bundle id and package name (the artifact pipeline verifies every build against them), edit metadata, and archive when an application retires.</li><li><strong>Own the version history</strong> — create versions, manage tags, archive old versions, and revoke distribution of a bad one. History stays readable forever; revocation blocks new downloads, it deletes nothing.</li><li><strong>Run releases</strong> — create and manage releases of your applications, and sign the <strong>Product approval</strong> step of their chains.</li><li><strong>Govern what your releases ride</strong> — define environments, approval workflows, gate definitions, rings, release policies, and ABAC policies (the same governance standing the Organization Admin and Release Manager hold).</li><li><strong>Decide visibility</strong> — authorize and de-authorize tenants for organization-shared applications, and manage the version grants that say which testers may install what.</li><li><strong>Triage feedback</strong> on your applications, read and recompute their analytics, and watch their dashboards.</li><li><strong>Route notifications</strong> for the events your releases emit.</li></ul><h2 id="first-15-minutes" tabindex="-1">First 15 minutes <a class="header-anchor" href="#first-15-minutes" aria-label="Permalink to &quot;First 15 minutes&quot;">​</a></h2><p>The screenshots come from the locally running development stack with its seeded demo world — what you see here is what you will see there.</p><ol><li><p><strong>Sign in and read the dashboard.</strong> The counts and per-application release health row give you the state of your products at a glance, and the pending-actions panel is where the Product approval steps waiting on your signature collect — each one a click away from the release it acts on. Nothing waiting means exactly that.</p><p><img src="'+n+'" alt="The dashboard as an App Owner"></p></li><li><p><strong>Register your application.</strong> Open <strong>Applications</strong> and create it: name, platforms (iOS, Android, or both), and the bundle id / package name the store builds carry. Those identifiers are pinned — the pipeline verifies every uploaded artifact against them, so a build claiming to be your app but signed for another bundle never lands.</p><p><img src="'+a+'" alt="The applications registry"></p></li><li><p><strong>Create the first version.</strong> Versions are semver-named and born as drafts; your <a href="/shipperdog/snapshot/roles/developer">Developers</a> upload the iOS and Android artifacts into the version&#39;s platform slots, and metadata extraction fills in the build details. You manage tags — <code>BETA</code>, <code>RC</code> — and the working-set rules that follow them.</p></li><li><p><strong>Open a release and check the manifest.</strong> When a release reaches approval, its manifest freezes: the exact content pins per platform with digests. That manifest is what every ring of the rollout serves — read <a href="/shipperdog/snapshot/concepts/artifact-pipeline">the artifact pipeline</a> for what happens between upload and READY.</p></li><li><p><strong>Watch your numbers.</strong> The application dashboards and release analytics show install success, crash-free sessions, and tester engagement per release and ring — the inputs the quality gates and your promotion decisions read.</p></li></ol><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><p>Hand-off task list:</p><ul><li>[ ] Read <a href="/shipperdog/snapshot/get-started/concepts">core concepts</a> if you have not</li><li>[ ] Read <a href="/shipperdog/snapshot/concepts/artifact-pipeline">the artifact pipeline</a> and <a href="/shipperdog/snapshot/concepts/release-lifecycle">the release lifecycle</a></li><li>[ ] Read <a href="/shipperdog/snapshot/concepts/feedback-analytics">feedback analytics</a> for the dashboards you will watch</li><li>[ ] How-tos as they land: <a href="/shipperdog/snapshot/how-to/console/apps">applications</a>, <a href="/shipperdog/snapshot/how-to/console/versions-and-tags">versions and tags</a>, <a href="/shipperdog/snapshot/how-to/console/analytics-and-dashboards">analytics and dashboards</a></li><li>[ ] Hand the <a href="/shipperdog/snapshot/roles/developer">Developer quickstart</a> to the team that ships your builds</li></ul>',11)])])}const y=t(i,[["render",l]]);export{m as __pageData,y as default};
